// The built-in card list. Generated by `npm run cards`; do not edit cards.json by hand.
import data from './data/cards.json';

export type Variant =
	| 'normal'
	| 'alt'
	| 'overnumbered'
	| 'signature'
	| 'rune'
	| 'special'
	| 'token'
	| 'promo';

export interface Card {
	/**
	 * Unique per printing. Riftcodex ids carry the set size ("ven-095-166"); cards that only
	 * Piltover Archive has do not ("rad-128").
	 */
	id: string;
	/** Set code, e.g. "VEN". */
	set: string;
	/** Collector number. Not unique inside a set: alternate art shares it with the normal card. */
	num: number;
	variant: Variant;
	name: string;
	type: string;
	supertype: string | null;
	rarity: string;
	domains: string[];
	landscape: boolean;
}

export interface CardSet {
	id: string;
	name: string;
	/** Release date, YYYY-MM-DD. Sets are listed oldest first. */
	published: string;
}

export const sets = data.sets as CardSet[];
export const cards = data.cards as Card[];

const byId = new Map(cards.map((c) => [c.id, c]));

export function cardById(id: string): Card | undefined {
	return byId.get(id.toLowerCase());
}

/** Finds a card by what is printed on it: set, number and, if printed, the set size. */
export function cardByPrint(set: string, number: string, total: string | null): Card | undefined {
	const short = `${set}-${number}`.toLowerCase();
	return (total ? byId.get(`${short}-${total}`) : undefined) ?? byId.get(short);
}
